from function import *
from sklearn.model_selection import train_test_split
from keras.utils import to_categorical
from keras.models import Sequential
from keras.layers import LSTM, Dense
from keras.callbacks import TensorBoard, EarlyStopping
import json
# Only train on letters whose keypoints were fully generated by data.py
def has_data(action):
    return all(os.path.isfile(os.path.join(DATA_PATH, action, str(sequence), "{}.npy".format(frame_num)))
               for sequence in range(no_sequences) for frame_num in range(sequence_length))
skipped = [action for action in actions if not has_data(action)]
if skipped:
    print('Skipping letters with no data in MP_Data (run data.py first):', ' '.join(skipped))
actions = np.array([action for action in actions if action not in skipped])
if len(actions) < 2:
    raise FileNotFoundError('Need data for at least 2 letters in MP_Data. Run collectdata.py and data.py first.')
print('Training on:', ' '.join(actions))
label_map = {label:num for num, label in enumerate(actions)}
# print(label_map)
sequences, labels = [], []
for action in actions:
    for sequence in range(no_sequences):
        window = []
        for frame_num in range(sequence_length):
            res = np.load(os.path.join(DATA_PATH, action, str(sequence), "{}.npy".format(frame_num)))
            window.append(normalize_keypoints(res))
        # Skip samples where MediaPipe found no hand in the image
        if not np.any(window):
            print(f'Skipping {action} sample {sequence}: no hand detected')
            continue
        sequences.append(window)
        labels.append(label_map[action])

X = np.array(sequences)
y = to_categorical(labels, num_classes=len(actions)).astype(int)
X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, stratify=labels, random_state=42)

# Augment training data with slightly jittered copies so the model
# tolerates small differences in hand shape between captures
rng = np.random.default_rng(42)
augmented = [X_train] + [X_train + rng.normal(0, 0.03, X_train.shape) for _ in range(10)]
X_train = np.concatenate(augmented)
y_train = np.concatenate([y_train] * len(augmented))

log_dir = os.path.join('Logs')
tb_callback = TensorBoard(log_dir=log_dir)
early_stop = EarlyStopping(monitor='val_loss', patience=20, restore_best_weights=True)
model = Sequential()
model.add(LSTM(64, return_sequences=True, input_shape=(30,63)))
model.add(LSTM(64, return_sequences=False))
model.add(Dense(64, activation='relu'))
model.add(Dense(actions.shape[0], activation='softmax'))

model.compile(optimizer='Adam', loss='categorical_crossentropy', metrics=['categorical_accuracy'])
model.fit(X_train, y_train, epochs=200, validation_data=(X_test, y_test), callbacks=[tb_callback, early_stop])
model.summary()
loss, accuracy = model.evaluate(X_test, y_test, verbose=0)
print(f'Test accuracy: {accuracy:.2%} on {len(X_test)} held-out samples')

model_json = model.to_json()
with open("model.json", "w") as json_file:
    json_file.write(model_json)
model.save('model.h5')
# Save which letters this model was trained on so app.py uses matching labels
with open("model_actions.json", "w") as actions_file:
    json.dump(actions.tolist(), actions_file)